     1→/**
     2→ * FreeWire - 그래프 스냅샷 / Undo-Redo 시스템
     3→ *
     4→ * GraphHistory: 그래프 JSON 상태를 스택에 쌓아
     5→ * undo / redo / clear 기능을 제공합니다.
     6→ */
     7→
     8→'use strict';
     9→
    10→const MAX_SIZE = 50;
    11→
    12→class GraphHistory {
    13→  /**
    14→   * @param {number} [maxSize=50]  히스토리 최대 보관 수
    15→   */
    16→  constructor(maxSize = MAX_SIZE) {
    17→    if (typeof maxSize !== 'number' || maxSize < 1) {
    18→      throw new Error('maxSize는 1 이상의 정수여야 합니다');
    19→    }
    20→    this._maxSize   = maxSize;
    21→    this._past      = [];   // 이전 상태 스택 (index 0 = 가장 오래됨)
    22→    this._future    = [];   // 되돌리기 취소 스택 (index 0 = 가장 최근 undo)
    23→  }
    24→
    25→  // ─── 주요 메서드 ────────────────────────────────────────────
    26→
    27→  /**
    28→   * 현재 그래프 상태를 직렬화하여 저장합니다.
    29→   * redo 스택은 새 push 시 비워집니다.
    30→   *
    31→   * @param {object|string} graphJson  Graph#toJSON() 결과 또는 JSON 문자열
    32→   */
    33→  push(graphJson) {
    34→    const snapshot = this._serialize(graphJson);
    35→    this._past.push(snapshot);
    36→    // 최대 개수 초과 시 가장 오래된 항목 제거
    37→    if (this._past.length > this._maxSize) {
    38→      this._past.shift();
    39→    }
    40→    // 새 상태가 추가되면 redo 스택 초기화
    41→    this._future = [];
    42→  }
    43→
    44→  /**
    45→   * 가장 최근 상태를 꺼내 반환합니다 (없으면 null).
    46→   * 꺼낸 상태는 redo 스택으로 이동합니다.
    47→   *
    48→   * @returns {object|null}  역직렬화된 그래프 JSON 또는 null
    49→   */
    50→  undo() {
    51→    if (!this.canUndo) return null;
    52→    const snapshot = this._past.pop();
    53→    this._future.push(snapshot);
    54→    return this._deserialize(snapshot);
    55→  }
    56→
    57→  /**
    58→   * 가장 최근 undo 상태를 꺼내 반환합니다 (없으면 null).
    59→   * 꺼낸 상태는 다시 past 스택으로 이동합니다.
    60→   *
    61→   * @returns {object|null}  역직렬화된 그래프 JSON 또는 null
    62→   */
    63→  redo() {
    64→    if (!this.canRedo) return null;
    65→    const snapshot = this._future.pop();
    66→    this._past.push(snapshot);
    67→    return this._deserialize(snapshot);
    68→  }
    69→
    70→  /**
    71→   * 모든 히스토리(past + future)를 초기화합니다.
    72→   */
    73→  clear() {
    74→    this._past    = [];
    75→    this._future  = [];
    76→  }
    77→
    78→  // ─── Getter ──────────────────────────────────────────────────
    79→
    80→  /** undo 가능 여부 */
    81→  get canUndo() {
    82→    return this._past.length > 0;
    83→  }
    84→
    85→  /** redo 가능 여부 */
    86→  get canRedo() {
    87→    return this._future.length > 0;
    88→  }
    89→
    90→  /**
    91→   * 현재 저장된 past 스냅샷 수
    92→   * (redo 스택은 포함하지 않음)
    93→   */
    94→  get size() {
    95→    return this._past.length;
    96→  }
    97→
    98→  // ─── 직렬화 헬퍼 ─────────────────────────────────────────────
    99→
   100→  _serialize(graphJson) {
   101→    if (typeof graphJson === 'string') return graphJson;
   102→    return JSON.stringify(graphJson);
   103→  }
   104→
   105→  _deserialize(snapshot) {
   106→    if (typeof snapshot === 'object') return snapshot;
   107→    return JSON.parse(snapshot);
   108→  }
   109→}
   110→
   111→module.exports = { GraphHistory };
   112→

