     1→/**
     2→ * FreeWire - data 노드 정의
     3→ * 상수, 변수, 배열, 객체, API 응답 등 값 공급 노드
     4→ */
     5→
     6→const { PORT_TYPES } = require('../node-spec');
     7→
     8→const DATA_TYPES = {
     9→  STRING:  'string',
    10→  NUMBER:  'number',
    11→  BOOLEAN: 'boolean',
    12→  ARRAY:   'array',
    13→  OBJECT:  'object',
    14→  STATE:   'state',    // 반응형 상태 (GlobalStateManager)
    15→  PROPS:   'props',    // 외부 입력 props
    16→};
    17→
    18→/**
    19→ * data 노드 생성
    20→ * @param {string} id
    21→ * @param {string} dataType - DATA_TYPES 중 하나
    22→ * @param {*}      value    - 초기값
    23→ * @param {object} opts     - { name, label }
    24→ */
    25→function createDataNode(id, dataType = 'string', value = '', opts = {}) {
    26→  const label = opts.label || DATA_TYPE_LABELS[dataType] || '데이터';
    27→
    28→  return {
    29→    id,
    30→    type:     'data',
    31→    dataType,
    32→    inputs:   dataType === 'state' || dataType === 'props'
    33→      ? [{ portId: 'initial', label: '초기값', portType: PORT_TYPES.DATA, required: false }]
    34→      : [],
    35→    outputs: [
    36→      { portId: 'value', label: '값', portType: PORT_TYPES.DATA },
    37→      ...(dataType === 'state'
    38→        ? [{ portId: 'setter', label: '변경 함수', portType: PORT_TYPES.LOGIC }]
    39→        : []),
    40→    ],
    41→    props: {
    42→      name:  opts.name || id,
    43→      label,
    44→      value,
    45→      ...(dataType === 'state'  ? { reactive: true }  : {}),
    46→      ...(dataType === 'props'  ? { required: false, defaultValue: value } : {}),
    47→      ...(dataType === 'array'  ? { itemType: 'any' } : {}),
    48→      ...(dataType === 'object' ? { schema: {} }      : {}),
    49→    },
    50→    meta: {
    51→      freelangBlock: dataType === 'props' ? 'props' : 'script',
    52→      position: { x: 0, y: 0 },
    53→    },
    54→  };
    55→}
    56→
    57→const DATA_TYPE_LABELS = {
    58→  string:  '문자열',
    59→  number:  '숫자',
    60→  boolean: '참/거짓',
    61→  array:   '배열',
    62→  object:  '객체',
    63→  state:   '상태(State)',
    64→  props:   '프롭스(Props)',
    65→};
    66→
    67→/**
    68→ * data 노드 → freelang-light 코드 변환
    69→ * @param {object} node
    70→ * @returns {string}
    71→ */
    72→function toFreelangCode(node) {
    73→  const { dataType, props } = node;
    74→  const val  = JSON.stringify(props.value);
    75→  const name = safeName(props.name);
    76→
    77→  switch (dataType) {
    78→    case 'state':
    79→      return [
    80→        `script {`,
    81→        `  let ${name} = ${val};`,
    82→        `  function set_${name}(v) { ${name} = v; }`,
    83→        `}`,
    84→      ].join('\n');
    85→
    86→    case 'props':
    87→      return [
    88→        `props {`,
    89→        `  ${name}: ${dataType} = ${val};`,
    90→        `}`,
    91→      ].join('\n');
    92→
    93→    case 'array':
    94→      return `script { let ${name} = ${val}; }`;
    95→
    96→    case 'object':
    97→      return `script { let ${name} = ${val}; }`;
    98→
    99→    default:
   100→      return `script { let ${name} = ${val}; }`;
   101→  }
   102→}
   103→
   104→/**
   105→ * 값 타입 자동 추론 (리터럴 입력 시)
   106→ * @param {*} value
   107→ * @returns {string} DATA_TYPES 중 하나
   108→ */
   109→function inferType(value) {
   110→  if (Array.isArray(value))       return DATA_TYPES.ARRAY;
   111→  if (value === null)             return DATA_TYPES.STRING;
   112→  switch (typeof value) {
   113→    case 'string':  return DATA_TYPES.STRING;
   114→    case 'number':  return DATA_TYPES.NUMBER;
   115→    case 'boolean': return DATA_TYPES.BOOLEAN;
   116→    case 'object':  return DATA_TYPES.OBJECT;
   117→    default:        return DATA_TYPES.STRING;
   118→  }
   119→}
   120→
   121→/**
   122→ * FreeLang 식별자 검증 (코드 인젝션 방지)
   123→ * @param {string} name
   124→ * @returns {string} 안전한 식별자 (영숫자+언더스코어만)
   125→ */
   126→function safeName(name) {
   127→  return String(name ?? 'var').replace(/[^\w]/g, '_');
   128→}
   129→
   130→module.exports = { DATA_TYPES, DATA_TYPE_LABELS, createDataNode, toFreelangCode, inferType, safeName };
   131→

