     1→/**
     2→ * FreeWire Phase 7 — Repair Engine
     3→ *
     4→ * 위반(Violation)을 받아서 최소한의 그래프 패치를 생성한다.
     5→ * 전체를 재생성하지 않고, 필요한 부분만 수술한다.
     6→ *
     7→ * 패치 타입:
     8→ *   add_wire    — 두 노드를 연결하는 와이어 추가
     9→ *   add_node    — 누락된 노드 추가 (+ 자동 위치 계산)
    10→ *   fix_prop    — 노드의 props 수정
    11→ *   remove_node — 의미 없는 노드 제거 (고아 노드)
    12→ */
    13→
    14→'use strict';
    15→
    16→let _repairIdCtr = 1;
    17→const rid = () => `rp-${_repairIdCtr++}`;
    18→
    19→// ─── 패치 구조 ─────────────────────────────────────────────────
    20→
    21→class GraphPatch {
    22→  constructor({ type, description, confidence, apply }) {
    23→    this.id          = rid();
    24→    this.type        = type;        // 'add_wire' | 'add_node' | 'fix_prop' | 'remove_node'
    25→    this.description = description; // 사람이 읽을 수 있는 설명
    26→    this.confidence  = confidence;  // 0-1, 이 패치가 맞을 확률
    27→    this._apply      = apply;       // (nodes, wires) => void
    28→  }
    29→
    30→  apply(nodes, wires) {
    31→    this._apply(nodes, wires);
    32→    return this;
    33→  }
    34→}
    35→
    36→// ─── Repair Engine ─────────────────────────────────────────────
    37→
    38→class RepairEngine {
    39→  /**
    40→   * 위반 목록 → 패치 목록 (신뢰도 순 정렬)
    41→   * @param {ContractViolation[]} violations
    42→   * @param {Map} nodes
    43→   * @param {Map} wires
    44→   * @returns {GraphPatch[]}
    45→   */
    46→  suggest(violations, nodes, wires) {
    47→    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    48→    const wiresArr = [...wires.values()];
    49→    const patches  = [];
    50→
    51→    // 구조적 경고도 수리 대상 (state 바인딩 등)
    52→    const FIXABLE_WARNINGS = new Set(['wire_state_to_display', 'connect_orphan']);
    53→
    54→    for (const v of violations) {
    55→      if (v.severity !== 'error' && !FIXABLE_WARNINGS.has(v.repairHint)) continue;
    56→
    57→      const p = this._violationToPatch(v, nodesArr, wiresArr);
    58→      if (p) patches.push(p);
    59→    }
    60→
    61→    // 신뢰도 높은 것 먼저, 중복 제거
    62→    return this._deduplicate(patches).sort((a, b) => b.confidence - a.confidence);
    63→  }
    64→
    65→  /**
    66→   * 패치들을 실제 그래프에 적용
    67→   * @param {GraphPatch[]} patches
    68→   * @param {Map} nodes
    69→   * @param {Map} wires
    70→   * @param {Function} nextId - ID 생성기
    71→   * @returns {{ applied: GraphPatch[], skipped: GraphPatch[] }}
    72→   */
    73→  applyPatches(patches, nodes, wires, nextId) {
    74→    const applied = [], skipped = [];
    75→
    76→    for (const patch of patches) {
    77→      try {
    78→        patch.apply(nodes, wires, nextId);
    79→        applied.push(patch);
    80→      } catch (e) {
    81→        skipped.push({ patch, reason: e.message });
    82→      }
    83→    }
    84→
    85→    return { applied, skipped };
    86→  }
    87→
    88→  // ─── 위반 → 패치 매핑 ──────────────────────────────────────
    89→
    90→  _violationToPatch(violation, nodesArr, wiresArr) {
    91→    const { repairHint, fact, nodeId, type } = violation;
    92→
    93→    // 버튼 ↔ 핸들러 연결 누락
    94→    if (repairHint === 'wire_handler_to_button' || fact === 'ui.button.connected') {
    95→      return this._patchWireHandlerToButton(nodeId, nodesArr, wiresArr);
    96→    }
    97→
    98→    // 핸들러 노드 자체가 없음
    99→    if (repairHint === 'add_handler_node' || fact === 'action.handler.present') {
   100→      return this._patchAddHandlerNode(nodesArr);
   101→    }
   102→
   103→    // state ↔ 텍스트 바인딩 누락
   104→    if (repairHint === 'wire_state_to_display' || fact === 'state.bound') {
   105→      return this._patchWireStateToDisplay(nodeId, nodesArr, wiresArr);
   106→    }
   107→
   108→    // 고아 노드 연결
   109→    if (repairHint === 'connect_orphan' || fact === 'node.connected') {
   110→      return this._patchConnectOrphan(nodeId, nodesArr, wiresArr);
   111→    }
   112→
   113→    // Goal fact 관련 수정
   114→    if (type === 'goal') return this._patchForGoalFact(fact, nodesArr, wiresArr);
   115→
   116→    // requires 미충족
   117→    if (type === 'requires') return this._patchRequires(violation, nodesArr, wiresArr);
   118→
   119→    return null;
   120→  }
   121→
   122→  _patchWireHandlerToButton(buttonId, nodesArr, wiresArr) {
   123→    const handlers = nodesArr.filter(n => n.subtype === 'handler');
   124→    if (handlers.length === 0) return null;
   125→
   126→    const handler = handlers[0];
   127→    return new GraphPatch({
   128→      type: 'add_wire',
   129→      description: `핸들러 "${handler.label ?? handler.id}"를 버튼에 연결 (onClick 포트)`,
   130→      confidence: 0.9,
   131→      apply: (nodes, wires, nextId) => {
   132→        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
   133→        wires.set(wireId, {
   134→          id: wireId,
   135→          fn: handler.id, fp: 0,  // handler의 output[0]
   136→          tn: buttonId,   tp: 1,  // button의 input[1] (onClick)
   137→        });
   138→      },
   139→    });
   140→  }
   141→
   142→  _patchAddHandlerNode(nodesArr) {
   143→    const buttons = nodesArr.filter(n => n.subtype === 'button');
   144→    if (buttons.length === 0) return null;
   145→
   146→    const lastBtn = buttons[buttons.length - 1];
   147→    const handlerName = this._guessHandlerName(lastBtn);
   148→    const newId = `handler-${Date.now()}`;
   149→
   150→    // 버튼 오른쪽에 배치
   151→    const bx = lastBtn.position?.x ?? 300;
   152→    const by = lastBtn.position?.y ?? 200;
   153→
   154→    return new GraphPatch({
   155→      type: 'add_node',
   156→      description: `이벤트 핸들러 "${handlerName}" 추가`,
   157→      confidence: 0.85,
   158→      apply: (nodes, wires, nextId) => {
   159→        const nid = nextId ? nextId() : newId;
   160→        nodes.set(nid, {
   161→          id: nid, type: 'logic', subtype: 'handler', label: `핸들러[${handlerName}]`,
   162→          inputs:  [{ name: 'action', portType: 'logic' }],
   163→          outputs: [{ name: 'handler', portType: 'logic' }],
   164→          props: { name: handlerName },
   165→          intent: '이벤트 처리',
   166→          contract: {
   167→            requires: [], ensures: ['action.handler.present', 'ui.button.connected'],
   168→            produces: ['action.handler.present', 'ui.button.connected'], warns: [],
   169→          },
   170→          position: { x: bx + 230, y: by },
   171→        });
   172→
   173→        // 버튼에 자동 연결
   174→        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
   175→        wires.set(wireId, { id: wireId, fn: nid, fp: 0, tn: lastBtn.id, tp: 1 });
   176→      },
   177→    });
   178→  }
   179→
   180→  _patchWireStateToDisplay(stateId, nodesArr, wiresArr) {
   181→    if (!stateId) return null;
   182→    const textNodes = nodesArr.filter(n => n.subtype === 'text');
   183→    if (textNodes.length === 0) return null;
   184→
   185→    // 엣지 구조가 {fn/tn} (RepairEngine 형식) 또는
   186→    // {from:{nodeId}, to:{nodeId}} (Graph 형식) 둘 다 지원
   187→    const getToId   = w => w.tn   ?? w.to?.nodeId   ?? w.to;
   188→    const getFromId = w => w.fn   ?? w.from?.nodeId ?? w.from;
   189→
   190→    // 아직 연결 안 된 텍스트 찾기
   191→    const unbound = textNodes.find(t =>
   192→      !wiresArr.some(w => getToId(w) === t.id && getFromId(w) === stateId)
   193→    );
   194→    if (!unbound) return null;
   195→
   196→    return new GraphPatch({
   197→      type: 'add_wire',
   198→      description: `상태를 텍스트 "${unbound.label}"에 바인딩`,
   199→      confidence: 0.8,
   200→      apply: (nodes, wires, nextId) => {
   201→        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
   202→        wires.set(wireId, { id: wireId, fn: stateId, fp: 0, tn: unbound.id, tp: 0 });
   203→      },
   204→    });
   205→  }
   206→
   207→  _patchConnectOrphan(orphanId, nodesArr, wiresArr) {
   208→    const orphan = nodesArr.find(n => n.id === orphanId);
   209→    if (!orphan) return null;
   210→
   211→    // 컨테이너나 카드를 찾아서 연결
   212→    const container = nodesArr.find(n =>
   213→      n.subtype === 'container' || n.subtype === 'card'
   214→    );
   215→    if (!container) return null;
   216→
   217→    return new GraphPatch({
   218→      type: 'add_wire',
   219→      description: `고아 노드 "${orphan.label}"를 컨테이너에 연결`,
   220→      confidence: 0.65,
   221→      apply: (nodes, wires, nextId) => {
   222→        const wireId = nextId ? nextId() : `rw-${Date.now()}`;
   223→        wires.set(wireId, { id: wireId, fn: orphanId, fp: 0, tn: container.id, tp: 0 });
   224→      },
   225→    });
   226→  }
   227→
   228→  _patchForGoalFact(fact, nodesArr, wiresArr) {
   229→    // 목표 fact에 따라 누락된 노드 제안
   230→    if (fact === 'auth.initiated' || fact === 'form.email.filled') {
   231→      const hasEmailInput = nodesArr.some(n =>
   232→        n.subtype === 'input' && n.props?.type === 'email'
   233→      );
   234→      if (!hasEmailInput) {
   235→        return new GraphPatch({
   236→          type: 'add_node',
   237→          description: '이메일 입력 필드 추가 (로그인에 필요)',
   238→          confidence: 0.75,
   239→          apply: (nodes, wires, nextId) => {
   240→            const nid = nextId ? nextId() : `email-${Date.now()}`;
   241→            nodes.set(nid, {
   242→              id: nid, type: 'component', subtype: 'input', label: '입력[이메일]',
   243→              inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
   244→              outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
   245→              props: { placeholder: '이메일', type: 'email' },
   246→              intent: '이메일 수집',
   247→              contract: {
   248→                requires: [], ensures: ['form.email.filled', 'data.available'],
   249→                produces: ['form.email.filled', 'data.available'], warns: [],
   250→              },
   251→              position: { x: 120, y: 120 },
   252→            });
   253→          },
   254→        });
   255→      }
   256→    }
   257→
   258→    if (fact === 'state.bound') {
   259→      return this._patchWireStateToDisplay(
   260→        nodesArr.find(n => n.subtype === 'state')?.id,
   261→        nodesArr, wiresArr
   262→      );
   263→    }
   264→
   265→    return null;
   266→  }
   267→
   268→  _patchRequires(violation, nodesArr, wiresArr) {
   269→    const { fact, nodeId } = violation;
   270→
   271→    // data.available이 필요한 경우 → state나 input 연결 찾기
   272→    if (fact === 'data.available') {
   273→      const dataNode = nodesArr.find(n => n.type === 'data');
   274→      const targetNode = nodesArr.find(n => n.id === nodeId);
   275→      if (!dataNode || !targetNode) return null;
   276→
   277→      return new GraphPatch({
   278→        type: 'add_wire',
   279→        description: `데이터 소스 "${dataNode.label}"를 "${targetNode.label}"에 연결`,
   280→        confidence: 0.7,
   281→        apply: (nodes, wires, nextId) => {
   282→          const wireId = nextId ? nextId() : `rw-${Date.now()}`;
   283→          wires.set(wireId, { id: wireId, fn: dataNode.id, fp: 0, tn: nodeId, tp: 0 });
   284→        },
   285→      });
   286→    }
   287→
   288→    return null;
   289→  }
   290→
   291→  // ─── 헬퍼 ────────────────────────────────────────────────────
   292→
   293→  _guessHandlerName(btn) {
   294→    const label = (btn.props?.label ?? '').toLowerCase();
   295→    if (/로그인|login/.test(label))  return 'handleLogin';
   296→    if (/\+|증가|inc/.test(label))   return 'handleIncrement';
   297→    if (/-|감소|dec/.test(label))    return 'handleDecrement';
   298→    if (/초기화|reset/.test(label))  return 'handleReset';
   299→    if (/제출|submit/.test(label))   return 'handleSubmit';
   300→    if (/검색|search/.test(label))   return 'handleSearch';
   301→    if (/추가|add/.test(label))      return 'handleAdd';
   302→    if (/삭제|del|remove/.test(label)) return 'handleDelete';
   303→    return 'handleClick';
   304→  }
   305→
   306→  _deduplicate(patches) {
   307→    const seen = new Set();
   308→    return patches.filter(p => {
   309→      const key = `${p.type}:${p.description}`;
   310→      if (seen.has(key)) return false;
   311→      seen.add(key);
   312→      return true;
   313→    });
   314→  }
   315→}
   316→
   317→module.exports = { RepairEngine, GraphPatch };
   318→

