     1→/**
     2→ * FreeWire Phase 8 — Pattern Advisor
     3→ *
     4→ * RepairHistory를 읽어서 "사전 경고"를 만든다.
     5→ *
     6→ * 그래프가 생성되기 전, 혹은 의도가 입력되는 순간:
     7→ * "이 노드 조합에서 과거에 X번 같은 실수가 났어요."
     8→ *
     9→ * 사후 수정이 아닌 사전 예방.
    10→ */
    11→
    12→'use strict';
    13→
    14→const { RepairHistory } = require('./repair-history');
    15→
    16→// ─── 조언 구조 ───────────────────────────────────────────────
    17→
    18→class PatternAdvice {
    19→  constructor({ pattern, occurrences, severity, message, preventionHint }) {
    20→    this.pattern        = pattern;        // "button:ui.button.connected"
    21→    this.occurrences    = occurrences;    // 과거 발생 횟수
    22→    this.severity       = severity;       // 'high' | 'medium' | 'low'
    23→    this.message        = message;        // 사람이 읽을 수 있는 경고
    24→    this.preventionHint = preventionHint; // 예방 방법
    25→  }
    26→}
    27→
    28→// ─── Pattern Advisor ────────────────────────────────────────
    29→
    30→class PatternAdvisor {
    31→  constructor(history) {
    32→    this._history = history instanceof RepairHistory
    33→      ? history
    34→      : new RepairHistory();
    35→  }
    36→
    37→  /**
    38→   * 현재 그래프를 보고 "이 조합에서 과거에 자주 실수했어요" 조언
    39→   * @param {object[]} nodesArr
    40→   * @returns {PatternAdvice[]}
    41→   */
    42→  advise(nodesArr) {
    43→    const advices = [];
    44→    const subtypes = nodesArr.map(n => n.subtype).filter(Boolean);
    45→
    46→    // 알려진 위험 패턴들 체크
    47→    for (const [fact, rule] of KNOWN_RISK_PATTERNS) {
    48→      if (!rule.condition(subtypes)) continue;
    49→
    50→      const count = this._countPatternOccurrences(rule.subtypes, fact);
    51→      if (count === 0) continue;
    52→
    53→      advices.push(new PatternAdvice({
    54→        pattern:        `${rule.subtypes.join('+')}:${fact}`,
    55→        occurrences:    count,
    56→        severity:       count >= 5 ? 'high' : count >= 2 ? 'medium' : 'low',
    57→        message:        rule.message(count),
    58→        preventionHint: rule.prevention,
    59→      }));
    60→    }
    61→
    62→    return advices.sort((a, b) => b.occurrences - a.occurrences);
    63→  }
    64→
    65→  /**
    66→   * 이력 기반 패치 신뢰도 보정
    67→   * RepairEngine이 생성한 patches의 confidence를 과거 효능으로 조정
    68→   * @param {GraphPatch[]} patches
    69→   * @returns {GraphPatch[]} confidence 보정된 패치들
    70→   */
    71→  adjustConfidence(patches) {
    72→    return patches.map(patch => {
    73→      // 패치의 repairHint는 description에서 추론하거나 violation에서 가져옴
    74→      const repairHint = this._inferRepairHint(patch);
    75→      const efficacy   = this._history.patchEfficacy(patch.type, repairHint);
    76→
    77→      // 이력이 충분하면 (>= 3번 시도) 효능으로 confidence 보정
    78→      const applied = this._getAppliedCount(patch.type, repairHint);
    79→      if (applied >= 3) {
    80→        // 과거 효능과 현재 confidence의 가중 평균
    81→        const adjusted = (patch.confidence * 0.4) + (efficacy * 0.6);
    82→        return { ...patch, confidence: Math.round(adjusted * 100) / 100 };
    83→      }
    84→
    85→      return patch;
    86→    });
    87→  }
    88→
    89→  /**
    90→   * 과거 학습에서 이 시점에 필요한 노드 타입 제안
    91→   * (아직 그래프에 없지만 자주 함께 쓰이는 노드들)
    92→   * @param {object[]} nodesArr
    93→   * @returns {{ subtype: string, reason: string, frequency: number }[]}
    94→   */
    95→  suggestMissingNodes(nodesArr) {
    96→    const subtypes = new Set(nodesArr.map(n => n.subtype).filter(Boolean));
    97→    const suggestions = [];
    98→
    99→    for (const [combo, missing] of COMMON_COMBOS) {
   100→      const hasAll = combo.every(s => subtypes.has(s));
   101→      if (!hasAll) continue;
   102→      if (subtypes.has(missing.subtype)) continue;
   103→
   104→      const count = this._history.patternCount(missing.subtype, missing.fact);
   105→      if (count > 0) {
   106→        suggestions.push({
   107→          subtype:   missing.subtype,
   108→          reason:    missing.reason,
   109→          frequency: count,
   110→        });
   111→      }
   112→    }
   113→
   114→    return suggestions.sort((a, b) => b.frequency - a.frequency);
   115→  }
   116→
   117→  /**
   118→   * 이 위반이 이 세션에서 처음인지, 반복인지
   119→   */
   120→  isRepeatedMistake(fact, nodeSubtype) {
   121→    return this._history.patternCount(nodeSubtype, fact) > 1;
   122→  }
   123→
   124→  /**
   125→   * 전체 학습 요약 리포트
   126→   */
   127→  learningReport() {
   128→    const stats = this._history.stats();
   129→    const top   = this._history.topViolations(5);
   130→
   131→    const lines = [
   132→      `📊 학습 리포트`,
   133→      `총 수정 이력: ${stats.totalRecords}회`,
   134→      `성공률: ${stats.successRate}%`,
   135→      ``,
   136→      `자주 발생한 위반:`,
   137→    ];
   138→
   139→    for (const v of top) {
   140→      const [subtype, fact] = v.pattern.split(':');
   141→      lines.push(`  · [${v.count}회] ${subtype} → ${fact}`);
   142→    }
   143→
   144→    return lines.join('\n');
   145→  }
   146→
   147→  // ─── 내부 헬퍼 ──────────────────────────────────────────
   148→
   149→  _countPatternOccurrences(subtypes, fact) {
   150→    return subtypes.reduce((acc, s) =>
   151→      acc + this._history.patternCount(s, fact), 0
   152→    );
   153→  }
   154→
   155→  _inferRepairHint(patch) {
   156→    // description에서 힌트 추론
   157→    const desc = patch.description ?? '';
   158→    if (/핸들러|handler/i.test(desc)) return 'add_handler_node';
   159→    if (/버튼.*연결|wire.*button/i.test(desc)) return 'wire_handler_to_button';
   160→    if (/상태.*바인딩|state.*bind/i.test(desc)) return 'wire_state_to_display';
   161→    if (/고아|orphan/i.test(desc)) return 'connect_orphan';
   162→    return patch.type;
   163→  }
   164→
   165→  _getAppliedCount(patchType, repairHint) {
   166→    const best = this._history.bestPatchFor(repairHint);
   167→    if (best?.patchType === patchType) return best.applied;
   168→    return 0;
   169→  }
   170→}
   171→
   172→// ─── 알려진 위험 패턴 ───────────────────────────────────────
   173→
   174→/**
   175→ * [fact, { condition, subtypes, message, prevention }]
   176→ * condition: (subtypes: string[]) => boolean
   177→ */
   178→const KNOWN_RISK_PATTERNS = new Map([
   179→  ['ui.button.connected', {
   180→    subtypes:  ['button'],
   181→    condition: ss => ss.includes('button') && !ss.includes('handler'),
   182→    message:   n => `버튼이 있는 그래프에서 핸들러 연결 누락이 ${n}번 발생했습니다.`,
   183→    prevention:'버튼을 추가할 때 핸들러 노드도 함께 추가하세요.',
   184→  }],
   185→  ['state.bound', {
   186→    subtypes:  ['state'],
   187→    condition: ss => ss.includes('state') && !ss.includes('text'),
   188→    message:   n => `상태 노드가 텍스트에 바인딩되지 않아 ${n}번 수정됐습니다.`,
   189→    prevention:'상태 노드 추가 시 텍스트 노드도 연결하세요.',
   190→  }],
   191→  ['data.available', {
   192→    subtypes:  ['handler'],
   193→    condition: ss => ss.includes('handler') && !ss.some(s => s === 'state' || s === 'input'),
   194→    message:   n => `핸들러에 데이터 소스 연결 누락이 ${n}번 발생했습니다.`,
   195→    prevention:'핸들러 노드에 state 또는 input 노드를 연결하세요.',
   196→  }],
   197→]);
   198→
   199→// ─── 자주 함께 쓰이는 조합 ──────────────────────────────────
   200→
   201→/**
   202→ * [있는 노드들, 없지만 있어야 할 노드]
   203→ */
   204→const COMMON_COMBOS = [
   205→  [['button'], { subtype: 'handler', fact: 'ui.button.connected', reason: '버튼 클릭 처리' }],
   206→  [['state'],  { subtype: 'text',    fact: 'state.bound',         reason: '상태 표시' }],
   207→  [['input'],  { subtype: 'state',   fact: 'data.available',      reason: '입력값 저장' }],
   208→  [['button', 'input'], { subtype: 'state', fact: 'data.available', reason: '폼 데이터 관리' }],
   209→];
   210→
   211→module.exports = { PatternAdvisor, PatternAdvice };
   212→

