     1→/**
     2→ * FreeWire Phase 10 — Adaptive Self-Correct Loop
     3→ *
     4→ * Phase 7의 SelfCorrectLoop + Phase 8의 RepairHistory + Phase 9의 ContractInferrer
     5→ * 모두가 하나로 합쳐진다.
     6→ *
     7→ * 이 루프는 단순히 수정하지 않는다.
     8→ *   1. 수정 전 — PatternAdvisor로 사전 경고 생성
     9→ *   2. 수정 중 — ContractInferrer로 누락 contract 자동 보완
    10→ *   3. 수정 후 — RepairHistory에 결과 기록
    11→ *   4. 다음 루프 — 기록된 효능으로 패치 신뢰도 보정
    12→ *
    13→ * 세션이 반복될수록 시스템이 나아진다.
    14→ * 이것이 "만족"이다.
    15→ */
    16→
    17→'use strict';
    18→
    19→const { IntentEvaluator }  = require('./evaluator');
    20→const { RepairEngine }     = require('./repair-engine');
    21→const { RepairHistory }    = require('./repair-history');
    22→const { PatternAdvisor }   = require('./pattern-advisor');
    23→const { ContractInferrer, mergeInferredContract } = require('./contract-inferrer');
    24→
    25→// ─── 전역 공유 이력 ─────────────────────────────────────────
    26→// 단일 인스턴스로 모든 세션 이력 축적
    27→const GLOBAL_HISTORY = new RepairHistory(1000);
    28→
    29→// ─── Adaptive Loop ──────────────────────────────────────────
    30→
    31→class AdaptiveLoop {
    32→  constructor({
    33→    maxIterations = 4,
    34→    targetScore   = 90,
    35→    history       = GLOBAL_HISTORY,
    36→    sessionId     = null,
    37→  } = {}) {
    38→    this.maxIterations = maxIterations;
    39→    this.targetScore   = targetScore;
    40→    this._history      = history;
    41→    this._sessionId    = sessionId ?? `s-${Date.now()}`;
    42→
    43→    this._evaluator = new IntentEvaluator();
    44→    this._repair    = new RepairEngine();
    45→    this._advisor   = new PatternAdvisor(history);
    46→    this._inferrer  = new ContractInferrer(history);
    47→  }
    48→
    49→  /**
    50→   * 단 하나의 공개 메서드.
    51→   *
    52→   * @param {string} goal
    53→   * @param {Map}    nodes   (mutable)
    54→   * @param {Map}    wires   (mutable)
    55→   * @param {Function} nextId
    56→   * @returns {AdaptiveLoopResult}
    57→   */
    58→  run(goal, nodes, wires, nextId = defaultNextId()) {
    59→    const trace         = [];
    60→    let   iteration     = 0;
    61→    let   lastReport    = null;
    62→    let   previousScore = 0;
    63→
    64→    // ── 사전 단계: Contract 자동 보완 ──────────────────────
    65→    const inferredContracts = this._inferrer.inferAll(nodes, wires, goal);
    66→    let inferCount = 0;
    67→    for (const [nodeId, inferred] of inferredContracts.entries()) {
    68→      const nodeView = nodes.get(nodeId);
    69→      if (nodeView) {
    70→        const def = nodeView.def ?? nodeView;
    71→        const merged = mergeInferredContract(def, inferred);
    72→        if (nodeView.def) nodeView.def = merged;
    73→        else nodes.set(nodeId, merged);
    74→        inferCount++;
    75→      }
    76→    }
    77→
    78→    // ── 사전 단계: 패턴 기반 사전 경고 ────────────────────
    79→    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    80→    const preAdvice = this._advisor.advise(nodesArr);
    81→
    82→    // ── 메인 루프 ─────────────────────────────────────────
    83→    while (iteration < this.maxIterations) {
    84→      iteration++;
    85→
    86→      // 1) 평가
    87→      const report = this._evaluator.evaluate(nodes, wires, goal);
    88→      lastReport   = report;
    89→
    90→      trace.push({
    91→        iteration,
    92→        score:      report.score,
    93→        errors:     report.errors.length,
    94→        warnings:   report.warnings.length,
    95→        patches:    [],
    96→        summary:    report.summary,
    97→        phase:      'evaluate',
    98→      });
    99→
   100→      if (report.passed && report.score >= this.targetScore) break;
   101→      if (report.errors.length === 0) break;
   102→
   103→      // 점수가 이전 이터레이션과 동일하면 스태그네이션 → 종료
   104→      if (iteration > 1 && report.score === trace[trace.length - 2]?.score) break;
   105→
   106→      // 2) 패치 생성 + 이력 기반 신뢰도 보정
   107→      let patches = this._repair.suggest(report.violations, nodes, wires);
   108→      patches = this._advisor.adjustConfidence(patches);
   109→
   110→      if (patches.length === 0) break;
   111→
   112→      // 3) 패치 적용
   113→      const { applied, skipped } = this._repair.applyPatches(patches, nodes, wires, nextId);
   114→
   115→      // 4) 이력 기록
   116→      const newReport = this._evaluator.evaluate(nodes, wires, goal);
   117→      for (const patch of applied) {
   118→        // patch.type 기반으로 violation 매핑 (Korean description 비교는 불안정)
   119→        const violation = report.violations.find(v =>
   120→          (patch.type === 'add_wire'   && (v.type === 'structural' || v.type === 'requires')) ||
   121→          (patch.type === 'add_node'   && v.type === 'structural') ||
   122→          (patch.type === 'fix_prop'   && v.type === 'requires') ||
   123→          (patch.type === 'remove_node'&& v.severity === 'warning')
   124→        ) ?? report.violations[0];
   125→
   126→        if (violation) {
   127→          this._history.record(
   128→            this._sessionId,
   129→            { ...violation, nodeSubtype: violation.nodeId
   130→              ? ([...nodes.values()].map(v => v.def ?? v).find(n => n.id === violation.nodeId)?.subtype)
   131→              : null
   132→            },
   133→            patch,
   134→            newReport.score,
   135→            previousScore,
   136→          );
   137→        }
   138→      }
   139→
   140→      trace[trace.length - 1].patches = applied.map(p => ({
   141→        type:        p.type,
   142→        description: p.description,
   143→        confidence:  p.confidence,
   144→      }));
   145→      trace[trace.length - 1].skipped = skipped.length;
   146→
   147→      previousScore = report.score;
   148→
   149→      if (applied.length === 0) break;
   150→    }
   151→
   152→    // ── 사후 분석 ─────────────────────────────────────────
   153→    const sessionSummary = this._history.sessionSummary(this._sessionId);
   154→    const learningSummary = this._buildLearningSummary(
   155→      preAdvice, inferCount, sessionSummary
   156→    );
   157→
   158→    return {
   159→      goal,
   160→      sessionId:       this._sessionId,
   161→      iterations:      iteration,
   162→      converged:       lastReport?.passed ?? false,
   163→      finalScore:      lastReport?.score  ?? 0,
   164→      trace,
   165→      finalReport:     lastReport,
   166→      improved:        trace.length > 1
   167→        ? (trace[trace.length - 1].score > trace[0].score)
   168→        : false,
   169→      // Phase 8-10 전용
   170→      preAdvice,
   171→      inferredContracts: inferCount,
   172→      learningSummary,
   173→      historyStats:    this._history.stats(),
   174→    };
   175→  }
   176→
   177→  _buildLearningSummary(preAdvice, inferCount, sessionSummary) {
   178→    const parts = [];
   179→    if (inferCount > 0) {
   180→      parts.push(`Contract 자동 추론: ${inferCount}개 노드`);
   181→    }
   182→    if (preAdvice.length > 0) {
   183→      const high = preAdvice.filter(a => a.severity === 'high');
   184→      parts.push(`사전 경고: ${preAdvice.length}개${high.length > 0 ? ` (고위험 ${high.length}개)` : ''}`);
   185→    }
   186→    if (sessionSummary) {
   187→      parts.push(`이번 세션: ${sessionSummary.totalPatches}회 수정, 성공 ${sessionSummary.improved}회`);
   188→    }
   189→    const globalStats = this._history.stats();
   190→    if (globalStats.totalRecords > 0) {
   191→      parts.push(`누적 학습: ${globalStats.totalRecords}회 / 성공률 ${globalStats.successRate}%`);
   192→    }
   193→    return parts.join(' | ') || '학습 데이터 없음 (첫 세션)';
   194→  }
   195→
   196→  /**
   197→   * 이 루프가 축적한 전체 학습 리포트
   198→   */
   199→  learningReport() {
   200→    return this._advisor.learningReport();
   201→  }
   202→
   203→  /**
   204→   * 이력 직접 접근 (테스트/저장용)
   205→   */
   206→  get history() { return this._history; }
   207→}
   208→
   209→// ─── 전역 이력 공유 루프 (싱글턴 패턴) ─────────────────────
   210→
   211→/**
   212→ * 매 호출마다 같은 이력을 공유하는 루프 생성
   213→ * 세션을 넘어서도 이력이 누적된다
   214→ */
   215→function createAdaptiveLoop(options = {}) {
   216→  return new AdaptiveLoop({ history: GLOBAL_HISTORY, ...options });
   217→}
   218→
   219→/**
   220→ * 전역 이력 초기화 (테스트용)
   221→ */
   222→function resetGlobalHistory() {
   223→  GLOBAL_HISTORY._records       = [];
   224→  GLOBAL_HISTORY._patternIndex  = new Map();
   225→  GLOBAL_HISTORY._efficacyIndex = new Map();
   226→}
   227→
   228→/**
   229→ * 전역 이력에 접근
   230→ */
   231→function getGlobalHistory() {
   232→  return GLOBAL_HISTORY;
   233→}
   234→
   235→// ─── ID 생성기 팩토리 ───────────────────────────────────────
   236→
   237→function defaultNextId() {
   238→  let ctr = Date.now();
   239→  return () => `al-${ctr++}`;
   240→}
   241→
   242→module.exports = {
   243→  AdaptiveLoop,
   244→  createAdaptiveLoop,
   245→  resetGlobalHistory,
   246→  getGlobalHistory,
   247→  defaultNextId,
   248→  GLOBAL_HISTORY,
   249→};
   250→

