     1→/**
     2→ * FreeWire Phase 14 - 캔버스 확장 모듈
     3→ *
     4→ * 포함 기능:
     5→ *   1. Minimap     — 캔버스 전체를 축소해서 보여주는 네비게이터
     6→ *   2. MultiSelect — Shift+클릭, 드래그 박스 다중 선택
     7→ *   3. UndoRedo    — GraphHistory 기반 Undo/Redo 어댑터
     8→ *   4. Shortcuts   — 키보드 단축키 라우터
     9→ */
    10→
    11→'use strict';
    12→
    13→const { GraphHistory } = typeof require !== 'undefined'
    14→  ? require('../core/graph-history')
    15→  : { GraphHistory: class { push(){}; undo(){ return null; } redo(){ return null; } get canUndo(){ return false; } get canRedo(){ return false; } } };
    16→
    17→// ─── 1. Minimap ─────────────────────────────────────────────────
    18→
    19→/**
    20→ * 캔버스의 모든 노드를 지정된 크기의 축소 맵으로 렌더링.
    21→ * DOM에 의존하지 않고 순수 계산으로 좌표 변환을 제공.
    22→ */
    23→class Minimap {
    24→  /**
    25→   * @param {object} options
    26→   * @param {number} options.width   미니맵 픽셀 너비 (기본 180)
    27→   * @param {number} options.height  미니맵 픽셀 높이 (기본 120)
    28→   * @param {number} options.padding 내부 여백 (기본 8)
    29→   */
    30→  constructor({ width = 180, height = 120, padding = 8 } = {}) {
    31→    this.width   = width;
    32→    this.height  = height;
    33→    this.padding = padding;
    34→  }
    35→
    36→  /**
    37→   * 노드 목록 → 미니맵 좌표 배열로 변환
    38→   * @param {Array<{id, x, y, w, h}>} nodes
    39→   * @returns {{ nodes: Array<{id, mx, my, mw, mh}>, viewport: {scale, offsetX, offsetY} }}
    40→   */
    41→  project(nodes) {
    42→    if (!nodes || nodes.length === 0) {
    43→      return { nodes: [], viewport: { scale: 1, offsetX: 0, offsetY: 0 } };
    44→    }
    45→
    46→    // 바운딩 박스 계산
    47→    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    48→    for (const n of nodes) {
    49→      const nx = n.x ?? 0, ny = n.y ?? 0;
    50→      const nw = n.w ?? 120, nh = n.h ?? 80;
    51→      minX = Math.min(minX, nx);
    52→      minY = Math.min(minY, ny);
    53→      maxX = Math.max(maxX, nx + nw);
    54→      maxY = Math.max(maxY, ny + nh);
    55→    }
    56→
    57→    const contentW = maxX - minX || 1;
    58→    const contentH = maxY - minY || 1;
    59→    const availW   = this.width  - this.padding * 2;
    60→    const availH   = this.height - this.padding * 2;
    61→    const scale    = Math.min(availW / contentW, availH / contentH);
    62→
    63→    // 중앙 정렬 오프셋
    64→    const scaledW  = contentW * scale;
    65→    const scaledH  = contentH * scale;
    66→    const offsetX  = this.padding + (availW - scaledW) / 2;
    67→    const offsetY  = this.padding + (availH - scaledH) / 2;
    68→
    69→    const projected = nodes.map(n => ({
    70→      id:  n.id,
    71→      mx:  Math.round((( n.x ?? 0) - minX) * scale + offsetX),
    72→      my:  Math.round((( n.y ?? 0) - minY) * scale + offsetY),
    73→      mw:  Math.max(4, Math.round((n.w ?? 120) * scale)),
    74→      mh:  Math.max(3, Math.round((n.h ?? 80)  * scale)),
    75→      selected: n.selected ?? false,
    76→    }));
    77→
    78→    return { nodes: projected, viewport: { scale, offsetX, offsetY, minX, minY } };
    79→  }
    80→
    81→  /**
    82→   * 미니맵 좌표 → 캔버스 월드 좌표 역변환
    83→   * @param {number} mx  미니맵 X
    84→   * @param {number} my  미니맵 Y
    85→   * @param {object} viewport  project()가 반환한 viewport
    86→   * @returns {{ worldX, worldY }}
    87→   */
    88→  toWorld(mx, my, viewport) {
    89→    const { scale, offsetX, offsetY, minX = 0, minY = 0 } = viewport;
    90→    return {
    91→      worldX: (mx - offsetX) / scale + minX,
    92→      worldY: (my - offsetY) / scale + minY,
    93→    };
    94→  }
    95→}
    96→
    97→// ─── 2. MultiSelect ─────────────────────────────────────────────
    98→
    99→/**
   100→ * 드래그 박스 + Shift+클릭 기반 다중 노드 선택 관리자
   101→ */
   102→class MultiSelect {
   103→  constructor() {
   104→    /** @type {Set<string>} 현재 선택된 노드 ID 집합 */
   105→    this.selected = new Set();
   106→    this._box = null;   // 드래그 박스: {x0,y0,x1,y1}
   107→  }
   108→
   109→  /** 선택 전체 해제 */
   110→  clear() {
   111→    this.selected.clear();
   112→  }
   113→
   114→  /**
   115→   * 노드 하나 토글 (Shift+클릭)
   116→   * @param {string} id
   117→   */
   118→  toggle(id) {
   119→    if (this.selected.has(id)) this.selected.delete(id);
   120→    else                        this.selected.add(id);
   121→  }
   122→
   123→  /**
   124→   * 단일 선택 (일반 클릭 — 기존 선택 해제)
   125→   * @param {string} id
   126→   */
   127→  selectOne(id) {
   128→    this.selected.clear();
   129→    this.selected.add(id);
   130→  }
   131→
   132→  /**
   133→   * 드래그 박스 시작
   134→   * @param {number} x  캔버스 월드 X
   135→   * @param {number} y  캔버스 월드 Y
   136→   */
   137→  beginBox(x, y) {
   138→    this._box = { x0: x, y0: y, x1: x, y1: y };
   139→  }
   140→
   141→  /**
   142→   * 드래그 박스 업데이트
   143→   * @param {number} x
   144→   * @param {number} y
   145→   */
   146→  updateBox(x, y) {
   147→    if (this._box) { this._box.x1 = x; this._box.y1 = y; }
   148→  }
   149→
   150→  /**
   151→   * 드래그 박스 종료 — 박스 안에 있는 노드 선택
   152→   * @param {Array<{id, x, y, w, h}>} nodes
   153→   * @param {boolean} additive  true면 기존 선택에 추가
   154→   * @returns {Set<string>} 새로 선택된 노드 ID 집합
   155→   */
   156→  endBox(nodes, additive = false) {
   157→    if (!this._box) return this.selected;
   158→    const { x0, y0, x1, y1 } = this._box;
   159→    this._box = null;
   160→
   161→    const rx = Math.min(x0, x1), ry = Math.min(y0, y1);
   162→    const rw = Math.abs(x1 - x0), rh = Math.abs(y1 - y0);
   163→
   164→    if (!additive) this.selected.clear();
   165→
   166→    for (const n of nodes) {
   167→      if (this._intersects(n.x ?? 0, n.y ?? 0, n.w ?? 120, n.h ?? 80, rx, ry, rw, rh)) {
   168→        this.selected.add(n.id);
   169→      }
   170→    }
   171→    return this.selected;
   172→  }
   173→
   174→  /** 현재 드래그 박스 좌표 반환 (정규화) */
   175→  getBox() {
   176→    if (!this._box) return null;
   177→    const { x0, y0, x1, y1 } = this._box;
   178→    return {
   179→      x: Math.min(x0, x1), y: Math.min(y0, y1),
   180→      w: Math.abs(x1 - x0), h: Math.abs(y1 - y0),
   181→    };
   182→  }
   183→
   184→  /** 두 AABB 교차 여부 */
   185→  _intersects(ax, ay, aw, ah, bx, by, bw, bh) {
   186→    return ax < bx + bw && ax + aw > bx &&
   187→           ay < by + bh && ay + ah > by;
   188→  }
   189→
   190→  /** 선택된 모든 노드를 delta 만큼 이동한 새 위치 계산 */
   191→  moveSelected(nodes, dx, dy) {
   192→    const result = [];
   193→    for (const n of nodes) {
   194→      if (this.selected.has(n.id)) {
   195→        result.push({ id: n.id, x: (n.x ?? 0) + dx, y: (n.y ?? 0) + dy });
   196→      }
   197→    }
   198→    return result;
   199→  }
   200→
   201→  get count() { return this.selected.size; }
   202→  has(id)     { return this.selected.has(id); }
   203→}
   204→
   205→// ─── 3. UndoRedo ────────────────────────────────────────────────
   206→
   207→/**
   208→ * GraphHistory를 에디터에 연결하는 어댑터.
   209→ * 스냅샷 저장/복원 인터페이스 제공.
   210→ */
   211→class UndoRedo {
   212→  /**
   213→   * @param {number} maxSize  최대 스냅샷 수 (기본 50)
   214→   */
   215→  constructor(maxSize = 50) {
   216→    this._history = new GraphHistory(maxSize);
   217→  }
   218→
   219→  /**
   220→   * 현재 그래프 상태를 스냅샷으로 저장
   221→   * @param {object} graphSnapshot  직렬화된 그래프 JSON
   222→   */
   223→  snapshot(graphSnapshot) {
   224→    this._history.push(graphSnapshot);
   225→  }
   226→
   227→  /**
   228→   * Undo — 이전 상태 반환
   229→   * @returns {object|null} 복원할 그래프 JSON, 없으면 null
   230→   */
   231→  undo() {
   232→    return this._history.undo();
   233→  }
   234→
   235→  /**
   236→   * Redo — 앞으로 이동
   237→   * @returns {object|null} 복원할 그래프 JSON, 없으면 null
   238→   */
   239→  redo() {
   240→    return this._history.redo();
   241→  }
   242→
   243→  get canUndo() { return this._history.canUndo; }
   244→  get canRedo() { return this._history.canRedo; }
   245→  get size()    { return this._history.size; }
   246→
   247→  /** 히스토리 전체 초기화 */
   248→  clear() {
   249→    this._history.clear();
   250→  }
   251→}
   252→
   253→// ─── 4. Shortcuts ───────────────────────────────────────────────
   254→
   255→/**
   256→ * 키보드 단축키 라우터.
   257→ * DOM에 의존하지 않고 { key, ctrl, shift, alt } 객체로 매칭.
   258→ */
   259→class Shortcuts {
   260→  constructor() {
   261→    /** @type {Array<{key, ctrl, shift, alt, handler}>} */
   262→    this._bindings = [];
   263→  }
   264→
   265→  /**
   266→   * 단축키 등록
   267→   * @param {string}   key      e.key 값 (대소문자 무관)
   268→   * @param {object}   mods     { ctrl?, shift?, alt? }
   269→   * @param {Function} handler  실행할 함수
   270→   */
   271→  bind(key, mods, handler) {
   272→    this._bindings.push({
   273→      key:   key.toLowerCase(),
   274→      ctrl:  !!mods.ctrl,
   275→      shift: !!mods.shift,
   276→      alt:   !!mods.alt,
   277→      handler,
   278→    });
   279→  }
   280→
   281→  /**
   282→   * 키 이벤트 처리
   283→   * @param {{ key, ctrlKey, shiftKey, altKey }} e  KeyboardEvent 또는 동등 객체
   284→   * @returns {boolean} 처리됐으면 true
   285→   */
   286→  handle(e) {
   287→    const k = (e.key || '').toLowerCase();
   288→    for (const b of this._bindings) {
   289→      if (b.key   !== k)          continue;
   290→      if (b.ctrl  !== !!e.ctrlKey)  continue;
   291→      if (b.shift !== !!e.shiftKey) continue;
   292→      if (b.alt   !== !!e.altKey)   continue;
   293→      b.handler(e);
   294→      return true;
   295→    }
   296→    return false;
   297→  }
   298→
   299→  /** 특정 키+모디파이어 조합의 핸들러 수 반환 */
   300→  countBindings(key, mods = {}) {
   301→    const k = key.toLowerCase();
   302→    return this._bindings.filter(b =>
   303→      b.key === k &&
   304→      b.ctrl  === !!mods.ctrl &&
   305→      b.shift === !!mods.shift &&
   306→      b.alt   === !!mods.alt
   307→    ).length;
   308→  }
   309→
   310→  /** 전체 바인딩 해제 */
   311→  clear() {
   312→    this._bindings = [];
   313→  }
   314→}
   315→
   316→// ─── 기본 단축키 세트 생성 ──────────────────────────────────────
   317→
   318→/**
   319→ * FreeWire 표준 단축키 세트를 등록하고 반환
   320→ * @param {object} handlers 각 액션 핸들러 맵
   321→ *   handlers.undo()
   322→ *   handlers.redo()
   323→ *   handlers.deleteSelected()
   324→ *   handlers.selectAll()
   325→ *   handlers.escape()
   326→ *   handlers.duplicate()
   327→ * @returns {Shortcuts}
   328→ */
   329→function createDefaultShortcuts(handlers = {}) {
   330→  const s = new Shortcuts();
   331→  const noop = () => {};
   332→
   333→  s.bind('z',      { ctrl: true  },            handlers.undo          || noop);
   334→  s.bind('z',      { ctrl: true, shift: true }, handlers.redo          || noop);
   335→  s.bind('y',      { ctrl: true  },            handlers.redo          || noop);
   336→  s.bind('delete', {},                          handlers.deleteSelected || noop);
   337→  s.bind('backspace', {},                       handlers.deleteSelected || noop);
   338→  s.bind('a',      { ctrl: true  },            handlers.selectAll     || noop);
   339→  s.bind('escape', {},                          handlers.escape        || noop);
   340→  s.bind('d',      { ctrl: true  },            handlers.duplicate     || noop);
   341→
   342→  return s;
   343→}
   344→
   345→// ─── 공개 API ──────────────────────────────────────────────────
   346→
   347→module.exports = { Minimap, MultiSelect, UndoRedo, Shortcuts, createDefaultShortcuts };
