     1→/**
     2→ * FreeWire Phase 12+ - AI 마케팅팀 대시보드 생성기
     3→ *
     4→ * FreeWire 노드 그래프 → 마케팅 분석 대시보드 자동 생성
     5→ *
     6→ * 흐름:
     7→ *   team-log.csv 또는 metrics JSON
     8→ *   → 노드 그래프 자동 구성
     9→ *   → GraphCompiler → .free 코드
    10→ *   → FreeExecutor   → HTML/CSS/JS
    11→ *   → 완성 대시보드
    12→ */
    13→
    14→'use strict';
    15→
    16→const path = require('path');
    17→const { GraphCompiler } = require('../compiler/graph-compiler');
    18→const { FreeExecutor }  = require('../api/free-executor');
    19→const { BrowserExecutor } = require('../wasm/browser-executor');
    20→
    21→const compiler    = new GraphCompiler();
    22→const executor    = new FreeExecutor();
    23→const browserExec = new BrowserExecutor();
    24→
    25→// ─── 데이터 → 노드 그래프 변환 ─────────────────────────────────
    26→
    27→/**
    28→ * 마케팅 메트릭 → FreeWire 노드 그래프 생성
    29→ * @param {object} metrics
    30→ * @returns {object} FreeWire 그래프 JSON
    31→ */
    32→function buildDashboardGraph(metrics) {
    33→  const {
    34→    blogViews     = 0,
    35→    socialEngagement = 0,
    36→    communityComments = 0,
    37→    contentCount  = 0,
    38→    agents        = [],
    39→    period        = '주간',
    40→  } = metrics;
    41→
    42→  const uid = () => `mkt-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    43→
    44→  // 노드 정의
    45→  // 컴포넌트 노드 팩토리 (inputs/outputs 포함)
    46→  const compNode = (componentType, props, x = 0, y = 0) => ({
    47→    id: uid(), type: 'component', componentType,
    48→    inputs:  [{ portId: 'data', label: '데이터', portType: 'data', required: false }],
    49→    outputs: [{ portId: 'out',  label: '컴포넌트', portType: 'component' }],
    50→    props,
    51→    meta: { position: { x, y } },
    52→  });
    53→
    54→  const titleNode = compNode('text',
    55→    { content: `FreeLang 마케팅 대시보드 (${period})`, tag: 'h1', color: '#6366f1' }, 0, 0);
    56→
    57→  const blogCard = compNode('card',
    58→    { title: '블로그 조회수', content: `${blogViews.toLocaleString()} views`, variant: 'default' }, 0, 120);
    59→
    60→  const socialCard = compNode('card',
    61→    { title: '소셜 참여율', content: `${socialEngagement.toFixed(1)}%`, variant: socialEngagement >= 5 ? 'glass' : 'default' }, 220, 120);
    62→
    63→  const communityCard = compNode('card',
    64→    { title: '커뮤니티 댓글', content: `${communityComments}개`, variant: 'default' }, 440, 120);
    65→
    66→  const contentCard = compNode('card',
    67→    { title: '콘텐츠 생산', content: `${contentCount}편`, variant: contentCount >= 3 ? 'glass' : 'default' }, 660, 120);
    68→
    69→  // KPI 달성도 계산
    70→  const kpiNodes = [];
    71→  const kpis = [
    72→    { label: '블로그 조회수',  current: blogViews,        target: 1000, unit: 'views' },
    73→    { label: '소셜 참여율',    current: socialEngagement, target: 5,    unit: '%' },
    74→    { label: '커뮤니티 댓글', current: communityComments, target: 5,    unit: '개/주' },
    75→    { label: '콘텐츠 생산',   current: contentCount,      target: 3,    unit: '편/주' },
    76→  ];
    77→
    78→  kpis.forEach((kpi, i) => {
    79→    const pct = Math.min(100, Math.round((kpi.current / kpi.target) * 100));
    80→    kpiNodes.push(compNode('text', {
    81→      content: `${kpi.label}: ${kpi.current}${kpi.unit} / 목표 ${kpi.target}${kpi.unit} (${pct}%)`,
    82→      tag: 'p',
    83→      color: pct >= 100 ? '#22c55e' : pct >= 70 ? '#f59e0b' : '#ef4444',
    84→    }, 0, 300 + i * 40));
    85→  });
    86→
    87→  // 에이전트 상태 노드
    88→  const agentStatusNode = compNode('card', {
    89→    title: 'AI 마케팅팀 상태',
    90→    content: agents.length > 0
    91→      ? agents.map(a => `${a.name}: ${a.status}`).join(' | ')
    92→      : 'CMO | Content Writer | Social | Community | Analytics',
    93→    variant: 'glass',
    94→  }, 0, 500);
    95→
    96→  // 컨테이너 조합
    97→  const metricsContainer = compNode('container',
    98→    { direction: 'row', gap: '16px', padding: '16px' }, 0, 100);
    99→
   100→  const kpiContainer = compNode('container',
   101→    { direction: 'column', gap: '8px', padding: '16px' }, 0, 280);
   102→
   103→  const rootContainer = compNode('container',
   104→    { direction: 'column', gap: '24px', padding: '24px' }, 0, 0);
   105→
   106→  const nodes = [
   107→    rootContainer, titleNode,
   108→    metricsContainer, blogCard, socialCard, communityCard, contentCard,
   109→    kpiContainer, ...kpiNodes,
   110→    agentStatusNode,
   111→  ];
   112→
   113→  // 엣지: 컨테이너에 자식 연결
   114→  let _edgeCtr = 0;
   115→  const mkEdge = (fromId, toId) => ({
   116→    id: `e-${++_edgeCtr}-${Date.now()}`,
   117→    from: { nodeId: fromId, portId: 'out',      portType: 'component' },
   118→    to:   { nodeId: toId,   portId: 'children', portType: 'component' },
   119→  });
   120→
   121→  const edges = [
   122→    mkEdge(titleNode.id,        rootContainer.id),
   123→    mkEdge(metricsContainer.id, rootContainer.id),
   124→    mkEdge(kpiContainer.id,     rootContainer.id),
   125→    mkEdge(agentStatusNode.id,  rootContainer.id),
   126→    mkEdge(blogCard.id,         metricsContainer.id),
   127→    mkEdge(socialCard.id,       metricsContainer.id),
   128→    mkEdge(communityCard.id,    metricsContainer.id),
   129→    mkEdge(contentCard.id,      metricsContainer.id),
   130→    ...kpiNodes.map(n => mkEdge(n.id, kpiContainer.id)),
   131→  ];
   132→
   133→  return {
   134→    id: `marketing-dashboard-${Date.now()}`,
   135→    label: `FreeLang 마케팅 대시보드 (${period})`,
   136→    nodes,
   137→    edges,
   138→  };
   139→}
   140→
   141→/**
   142→ * 마케팅 메트릭 → 완성된 대시보드 HTML 생성
   143→ * @param {object} metrics
   144→ * @returns {{ html: string, css: string, js: string, preview: string, graph: object }}
   145→ */
   146→function generateDashboard(metrics = {}) {
   147→  const graph    = buildDashboardGraph(metrics);
   148→  const compiled = compiler.compile(graph);
   149→
   150→  // BrowserExecutor로 고품질 HTML 생성
   151→  const result   = browserExec.execute(compiled.code);
   152→  const preview  = browserExec.buildPreviewHTML(result);
   153→
   154→  return {
   155→    html:    result.html,
   156→    css:     result.css,
   157→    js:      result.js,
   158→    preview,
   159→    graph,
   160→    compiled: compiled.code,
   161→    stats:   result.stats,
   162→    warnings: compiled.warnings,
   163→  };
   164→}
   165→
   166→/**
   167→ * team-log.csv 파싱 → 메트릭 집계
